#!/bin/bash
# Last update: 13/10/2026

# Merge the per-subject IDP files (generated by idp_extract_part_1.sh) into the group-level files:
#   IDPs.tsv : tab-separated, with a header row
#   IDPs.txt : space-separated, no header (backward compatible)
#
# The subjects are written in the order of the input list. A subject without a valid IDPs.txt
# (missing, or with a wrong number of values) is written as a row of NaNs and listed in
# <list folder>/missing_subjects.txt

# -e  Exit immediately if a command exits with a non-zero status.
set -e

source $BRC_GLOBAL_SCR/log.shlib  # Logging related functions

# function for parsing options
getopt1()
{
    local sopt="$1"
    shift 1
    local fn
    for fn in "$@" ; do
        case "$fn" in
            "${sopt}"=*) printf '%s\n' "${fn#*=}"; return 0 ;;
        esac
    done
}

# parse arguments
ListFolder=`getopt1 "--listfolder" $@`
SubjectList_name=`getopt1 "--subjectlist_name" $@`
InputDIR=`getopt1 "--inputdir" $@`
AnalysisFolderName=`getopt1 "--analysisfoldername" $@`
IDP_folder_name=`getopt1 "--idp_folder_name" $@`
GroupIDPFolder=`getopt1 "--groupidpfolder" $@`
Start_Time=`getopt1 "--starttime" $@`
logIDPFolder=`getopt1 "--logidpfolder" $@`

log_SetPath "${logIDPFolder}"

MissingList=${ListFolder}/missing_subjects.txt

#=====================================================================================
###                                 Build the header row
#=====================================================================================

# --- Part 1: shell-script IDPs from IDP_list.txt (column 2 = IDP short name) ---
shell_headers=`awk '{print $2}' ${BRC_GLOBAL_DIR}/config/IDP_list.txt | tr '\n' ' '`

# --- Part 2: FreeSurfer IDPs from FS_headers.txt (skip first entry "ID" as
#             subject ID is already in column 1 of the output) ---
fs_headers=`tail -n +2 ${BRC_GLOBAL_DIR}/config/FS_headers.txt | tr '\n' ' '`

# --- Part 3: rfMRI IDPs from rfMRI_headers.txt ---
rfmri_headers=`cat ${BRC_GLOBAL_DIR}/config/rfMRI_headers.txt | tr '\n' ' '`

# Assemble full header: SubjectID + all IDP names
full_header="SubjectID ${shell_headers}${fs_headers}${rfmri_headers}"
full_header=`echo $full_header | sed 's/  */ /g'`

nCols=`echo $full_header | wc -w`
nan_row=`printf 'NaN %.0s' $(seq 2 ${nCols})`

# Write headers to group-level TSV (tab-separated with header)
echo "$full_header" | tr ' ' '\t' > ${GroupIDPFolder}/IDPs.tsv

# Plain text file (no header, space-separated — preserves backward compatibility)
if [ -e ${GroupIDPFolder}/IDPs.txt ] ; then rm ${GroupIDPFolder}/IDPs.txt; fi
touch ${GroupIDPFolder}/IDPs.txt

log_Msg 2 "Header row written to IDPs.tsv (${GroupIDPFolder}/IDPs.tsv), ${nCols} columns"

#=====================================================================================
###                                   DO WORK
#=====================================================================================

if [ -e ${MissingList} ] ; then rm ${MissingList}; fi

nSubj=0
nMissing=0

for Subject in $(cat ${ListFolder}/${SubjectList_name}) ; do
    nSubj=$(( nSubj + 1 ))

    SubjIDPs=${InputDIR}/${Subject}/${AnalysisFolderName}/${IDP_folder_name}/IDPs.txt

    result=""
    if [ -s ${SubjIDPs} ] ; then
        result=`cat ${SubjIDPs}`
        nSubjCols=`echo $result | wc -w`

        if [ ${nSubjCols} -ne ${nCols} ] ; then
            log_Msg 3 "${Subject}: ${nSubjCols} values in ${SubjIDPs} instead of ${nCols}, the subject is set to NaN"
            result=""
        fi
    else
        log_Msg 3 "${Subject}: ${SubjIDPs} does not exist, the subject is set to NaN"
    fi

    if [ "X${result}" = "X" ] ; then
        result=`echo "${Subject} ${nan_row}" | sed 's/  */ /g; s/ $//'`
        echo ${Subject} >> ${MissingList}
        nMissing=$(( nMissing + 1 ))
    fi

    # Append to group-level plain text file (no header, backward compatible)
    echo $result >> ${GroupIDPFolder}/IDPs.txt

    # Append to group-level TSV (tab-separated, has header from above)
    echo $result | tr ' ' '\t' >> ${GroupIDPFolder}/IDPs.tsv
done

log_Msg 3 "Merged ${nSubj} subjects, ${nMissing} missing"
if [ ${nMissing} -gt 0 ] ; then
    log_Msg 3 "The missing subjects are listed in ${MissingList}"
fi

END_Time="$(date -u +%s)"

${RUN} ${BRCDIR}/Show_version.sh \
      --showdiff="yes" \
      --start=${Start_Time} \
      --end=${END_Time} \
      --type=5 \
      --logfile=${logIDPFolder}
